mapper.select:
/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectCoseDirectivityResultList - 응용2팀 지원 정원제 */ SELECT B.WRTR_ID AS ID, /* 아이디 */ TO_CHAR(B.WRT_DT, 'YYYY-MM-DD AM HH12:MI:SS') AS YMD, /* 실시일자 */ CASE WHEN B.SXDC_SE_CD = 'F' THEN '여' WHEN B.SXDC_SE_CD = 'M' THEN '남' ELSE ' ' END AS SXDC, /* 성별 */ REPLACE(B.WEPOS_SUM_CN,'b:','') AS SCORE, /* 원점수 */ REPLACE(B.WEPOS_RESULT_DTL_NM,'b:','') AS RESULT /* 결과 */ FROM AYD440 B WHERE 1=1 AND B.KOGU_PVSN_NO = #{WEPOS_MLSFC_SN} /* 가이던스번호 */
AND B.FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
ORDER BY B.WRTR_ID, B.WRT_DT

/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectGnrlCharctPreconList - 응용2팀 지원 정원제 */ SELECT MAX(A.WEPOS_FCTR_NM1) AS NM, /* 패턴명 */ NVL(SUM(CASE WHEN A.WEPOS_FCTR_NM = 'e' AND SUBSTR(B.WEPOS_RESULT_NM,3,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 'i' AND SUBSTR(B.WEPOS_RESULT_NM,7,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 'o' AND SUBSTR(B.WEPOS_RESULT_NM,11,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 's' AND SUBSTR(B.WEPOS_RESULT_NM,15,1) = 'L' THEN 1 ELSE 0 END),0) AS LCNT, /* 하 */ NVL(SUM(CASE WHEN A.WEPOS_FCTR_NM = 'e' AND SUBSTR(B.WEPOS_RESULT_NM,3,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 'i' AND SUBSTR(B.WEPOS_RESULT_NM,7,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 'o' AND SUBSTR(B.WEPOS_RESULT_NM,11,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 's' AND SUBSTR(B.WEPOS_RESULT_NM,15,1) = 'M' THEN 1 ELSE 0 END),0) AS MCNT, /* 중 */ NVL(SUM(CASE WHEN A.WEPOS_FCTR_NM = 'e' AND SUBSTR(B.WEPOS_RESULT_NM,3,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 'i' AND SUBSTR(B.WEPOS_RESULT_NM,7,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 'o' AND SUBSTR(B.WEPOS_RESULT_NM,11,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 's' AND SUBSTR(B.WEPOS_RESULT_NM,15,1) = 'H' THEN 1 ELSE 0 END),0) AS HCNT, /* 상 */ COUNT(*) AS CNT /* 합계 */ FROM AYD430 A , AYD440 B WHERE 1=1 AND A.TRL_INSP_MNG_NO = #{TRL_INSP_MNG_NO} /* 관리번호 */ AND A.QESITM_NO IN ('1','2','3','4') /* 패턴 */ AND B.KOGU_PVSN_NO = #{WEPOS_MLSFC_SN} /* 가이던스번호 */
AND B.FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
GROUP BY A.WEPOS_FCTR_NM ORDER BY A.WEPOS_FCTR_NM

/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectGnrlCharctResultList - 응용2팀 지원 정원제 */ WITH PETTERN AS ( SELECT MAX(CASE WHEN WEPOS_FCTR_NM = 'e' THEN WEPOS_FCTR_NM1 || ':' ELSE '' END) E, MAX(CASE WHEN WEPOS_FCTR_NM = 'i' THEN WEPOS_FCTR_NM1 || ':' ELSE '' END) I, MAX(CASE WHEN WEPOS_FCTR_NM = 'o' THEN WEPOS_FCTR_NM1 || ':' ELSE '' END) O, MAX(CASE WHEN WEPOS_FCTR_NM = 's' THEN WEPOS_FCTR_NM1 || ':' ELSE '' END) S FROM AYD430 WHERE TRL_INSP_MNG_NO = #{TRL_INSP_MNG_NO} ) SELECT B.WRTR_ID AS ID, /* 아이디 */ TO_CHAR(B.WRT_DT, 'YYYY-MM-DD AM HH12:MI:SS') AS YMD, /* 실시일자 */ REPLACE(REPLACE(REPLACE(REPLACE(B.WEPOS_SUM_CN, 'e:',PT.E),'i:',PT.I),'o:',PT.O),'s:',PT.S) AS SCORE, /* 원점수 */ REPLACE(REPLACE(REPLACE(REPLACE(B.WEPOS_RESULT_DTL_NM,'e:',PT.E),'i:',PT.I),'o:',PT.O),'s:',PT.S) AS RESULT /* 결과 */ FROM AYD440 B , PETTERN PT WHERE 1=1 AND B.KOGU_PVSN_NO = #{WEPOS_MLSFC_SN} /* 가이던스번호 */
AND B.FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
ORDER BY B.WRTR_ID, B.WRT_DT

/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectEmtStableResultList - 응용2팀 지원 정원제 */ SELECT B.WRTR_ID AS ID, /* 아이디 */ TO_CHAR(B.WRT_DT, 'YYYY-MM-DD AM HH12:MI:SS') AS YMD, /* 실시일자 */ CASE WHEN B.ACBG_SE_CD = '1' THEN '초등' WHEN B.ACBG_SE_CD = '2' THEN '중등' WHEN B.ACBG_SE_CD = '3' THEN '고등' WHEN B.ACBG_SE_CD = '4' THEN '대학' WHEN B.ACBG_SE_CD = 'G' THEN '일반성인 ' ELSE ' ' END AS ACBG, /* 학교 */ CASE WHEN B.SXDC_SE_CD = 'F' THEN '여' WHEN B.SXDC_SE_CD = 'M' THEN '남' ELSE ' ' END AS SXDC, /* 성별 */ REPLACE(B.WEPOS_SUM_CN, 'b:','') AS SCORE, /* 원점수 */ REPLACE(B.WEPOS_RESULT_DTL_NM,'b:','') AS RESULT /* 결과 */ FROM AYD440 B WHERE 1=1 AND B.KOGU_PVSN_NO = #{WEPOS_MLSFC_SN} /* 가이던스번호 */
AND B.FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
ORDER BY B.WRTR_ID, B.WRT_DT

/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectMomNurtureEfficaPreconList - 응용2팀 지원 정원제 */ SELECT MAX(A.WEPOS_FCTR_NM1) AS NM, /* 패턴명 */ NVL(SUM(CASE WHEN A.WEPOS_FCTR_NM = 'a' AND SUBSTR(B.WEPOS_RESULT_NM,6,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 'b' AND SUBSTR(B.WEPOS_RESULT_NM,10,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 'c' AND SUBSTR(B.WEPOS_RESULT_NM,14,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 'd' AND SUBSTR(B.WEPOS_RESULT_NM,18,1) = 'L' THEN 1 WHEN A.WEPOS_FCTR_NM = 'e' AND SUBSTR(B.WEPOS_RESULT_NM,22,1) = 'L' THEN 1 ELSE 0 END),0) AS LCNT, /* 하 */ NVL(SUM(CASE WHEN A.WEPOS_FCTR_NM = 'a' AND SUBSTR(B.WEPOS_RESULT_NM,6,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 'b' AND SUBSTR(B.WEPOS_RESULT_NM,10,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 'c' AND SUBSTR(B.WEPOS_RESULT_NM,14,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 'd' AND SUBSTR(B.WEPOS_RESULT_NM,18,1) = 'M' THEN 1 WHEN A.WEPOS_FCTR_NM = 'e' AND SUBSTR(B.WEPOS_RESULT_NM,22,1) = 'M' THEN 1 ELSE 0 END),0) AS MCNT, /* 중 */ NVL(SUM(CASE WHEN A.WEPOS_FCTR_NM = 'a' AND SUBSTR(B.WEPOS_RESULT_NM,6,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 'b' AND SUBSTR(B.WEPOS_RESULT_NM,10,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 'c' AND SUBSTR(B.WEPOS_RESULT_NM,14,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 'd' AND SUBSTR(B.WEPOS_RESULT_NM,18,1) = 'H' THEN 1 WHEN A.WEPOS_FCTR_NM = 'e' AND SUBSTR(B.WEPOS_RESULT_NM,22,1) = 'H' THEN 1 ELSE 0 END),0) AS HCNT, /* 상 */ COUNT(*) AS CNT /* 합계 */ FROM AYD430 A , AYD440 B WHERE 1=1 AND A.TRL_INSP_MNG_NO = #{TRL_INSP_MNG_NO} /* 관리번호 */ AND A.QESITM_NO IN ('1','2','3','17','18') /* 패턴 */ AND B.KOGU_PVSN_NO = #{WEPOS_MLSFC_SN} /* 가이던스번호 */
AND B.FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
GROUP BY A.WEPOS_FCTR_NM ORDER BY A.WEPOS_FCTR_NM

/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectWebTrlInspProbmSttsList - 응용2팀 지원 정원제 */ SELECT AA.NO AS NO, /* 검사번호 */ AA.NM AS NM, /* 검사종류 */ 0 AS PROBM_STTS_01, 0 AS PROBM_STTS_02, CASE WHEN AA.NO IN ('11','12','16','51') THEN NVL(BB.CNT,0) ELSE 0 END AS PROBM_STTS_03, /* 대인관계 */ CASE WHEN AA.NO IN ('21','22','23','24','25','26') THEN NVL(BB.CNT,0) ELSE 0 END AS PROBM_STTS_04, /* 학업진로 */ CASE WHEN AA.NO IN ('31','32','33','34','35','36') THEN NVL(BB.CNT,0) ELSE 0 END AS PROBM_STTS_05, /* 과의존·중독 */ CASE WHEN AA.NO IN ('41','410','43','45','46','47','48','52','53') THEN NVL(BB.CNT,0) ELSE 0 END AS PROBM_STTS_06, /* 정신건강 */ 0 AS PROBM_STTS_07, 0 AS PROBM_STTS_08, 0 AS PROBM_STTS_09, 0 AS PROBM_STTS_10, 0 AS PROBM_STTS_11, 0 AS PROBM_STTS_12, 0 AS PROBM_STTS_13, 0 AS PROBM_STTS_14, 0 AS PROBM_STTS_99 FROM ( SELECT ADDTNG_MNG_VALUE1 AS NO, /* 검사번호 */ CMMNS_CD_VALUE_NM AS NM /* 검사종류 */ FROM SAC100 WHERE CMMNS_CD_ID = 'TRL_INSP_MLSFC_TYPE_SE_CD' AND USE_YN = 'Y' AND ADDTNG_MNG_VALUE1 IS NOT NULL ) AA, ( SELECT KOGU_PVSN_NO AS NO, COUNT(*) AS CNT FROM AYD440 WHERE 1=1
AND FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
GROUP BY KOGU_PVSN_NO ) BB WHERE AA.NO = BB.NO(+) ORDER BY AA.NO

/* * isry.couns.stats.dscsnstats.mapper.WebTrlInspStatsMapper.selectWebTrlInspDgstfnKndLIst - 응용2팀 지원 정원제 */ SELECT AA.NO AS NO, /* 검사번호 */ AA.NM AS NM, /* 검사종류 */ NVL(BB.CNT,0) AS CNT FROM ( SELECT ADDTNG_MNG_VALUE1 NO, /* 검사번호 */ CMMNS_CD_VALUE_NM NM /* 검사종류 */ FROM SAC100 WHERE CMMNS_CD_ID = 'TRL_INSP_MLSFC_TYPE_SE_CD' AND USE_YN = 'Y' AND ADDTNG_MNG_VALUE1 IS NOT NULL ) AA, ( SELECT A.TRL_INSP_SN NO, COUNT(*) CNT FROM AYE100 A , AYE195 B WHERE 1=1 AND A.BBSCTT_TYPE_SE_CD = #{BBSCTT_TYPE_SE_CD} AND A.BBSCTT_ESNTAL_NO = B.BBSCTT_ESNTAL_NO AND A.BBSCTT_TYPE_SE_CD = B.BBSCTT_TYPE_SE_CD
AND B.FRST_REG_DT >= TO_DATE(#{START_DT} || '000000', 'YYYYMMDDHH24MISS') AND B.FRST_REG_DT <= TO_DATE(#{END_DT} || '235959', 'YYYYMMDDHH24MISS')
AND A.DEL_YN = 'N' AND B.DEL_YN = 'N' GROUP BY A.TRL_INSP_SN ) BB WHERE AA.NO = BB.NO(+) ORDER BY AA.NO
